        const align = HCA7Kid(p, 'a', 'pPr')?.getAttribute('algn');
        lines.push({ text: (bullet ? '• ' : '') + text, font, size: Math.max(8, size), indent: lvl * size * 1.2, color: HCA7Color(rPr) || (title ? '#1f2937' : '#222222'), align });
