            await walk(el, { ox: t.ox + (+off.getAttribute('x') - t.cx) * t.sx, oy: t.oy + (+off.getAttribute('y') - t.cy) * t.sy, cx: +(cOff?.getAttribute('x') || 0), cy: +(cOff?.getAttribute('y') || 0), sx: sx * t.sx, sy: sy * t.sy });
