    obj(imgN, () => { push(`<< /Type /XObject /Subtype /Image /Width ${s.canvas.width} /Height ${s.canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`); push(jpg); push('\nendstream'); });
