        const ac = HCA9Snd.ctx, src = ac.createBufferSource(); src.buffer = HCA9Noise(ac, kind === 'rain' ? 'pink' : kind); src.loop = true;
        HCA9Snd.gain ||= ac.createGain(); HCA9Snd.gain.gain.value = vol;
