/* HCA v10 — first-visit hook, OS dark mode, mobile "More" sheet, desk-window focus and Escape, usage limits.
   Shares the bundle's module scope like the earlier layers (y = workspace context hook, HC = createElement,
   A = dialog, k = button, bs = main destinations, we = due cards, se = sample sources). */

const HCA10 = { state: null };
const HCA10Get = key => { try { return localStorage.getItem(key) || ''; } catch { return ''; } };
const HCA10Put = (key, value) => { try { localStorage.setItem(key, value); } catch { } };
