/* ---------- Theme: follow the device unless the learner picked one ---------- */
const HCA10ThemeKey = 'lumen.themeChosen';
const HCA10OsDark = () => !!globalThis.matchMedia?.('(prefers-color-scheme: dark)').matches;
function HCA10EffectiveTheme(theme) {
  return HCA10Get(HCA10ThemeKey) || HCA10.autoTheme === undefined ? theme : HCA10.autoTheme;
}
function HCA10ThemeSync() {
  const ctx = y(), theme = ctx.state.settings.theme, prev = _.useRef(null);
  _.useEffect(() => {
    // A saved "dark" predates this layer and the app's default is light, so it was the learner's choice.
    if (!HCA10Get(HCA10ThemeKey) && theme === 'dark' && !HCA10OsDark()) HCA10Put(HCA10ThemeKey, 'dark');
    if (HCA10Get(HCA10ThemeKey)) return;
    const mq = globalThis.matchMedia?.('(prefers-color-scheme: dark)');
    const apply = () => {
      if (HCA10Get(HCA10ThemeKey)) return;
      HCA10.autoTheme = mq?.matches ? 'dark' : 'light';
      HCA3SetSettings(ctx, { theme: HCA10.autoTheme });
    };
    apply();
    mq?.addEventListener?.('change', apply);
    return () => mq?.removeEventListener?.('change', apply);
  }, []);
  _.useEffect(() => {
    if (prev.current !== null && theme !== prev.current && theme !== HCA10.autoTheme) { HCA10Put(HCA10ThemeKey, theme); HCA10.autoTheme = undefined; }
    prev.current = theme;
  }, [theme]);
  return null;
}
if (!HCA10Get(HCA10ThemeKey)) { HCA10.autoTheme = HCA10OsDark() ? 'dark' : 'light'; if (HCA10.autoTheme === 'dark') document.documentElement.dataset.theme = 'dark'; }

/* ---------- First-visit hook ---------- */
